import Foundation
import Testing
@testable import AppleTVKit

/// Vector generated with srptools 1.0.1 (the library pyatv relies on for HAP pairing).
@Suite struct SRPTests {
    @Test func matchesReferenceImplementation() throws {
        let client = SRPClient(
            password: "1234",
            privateKey: Data(hexString: "60975527035cf2ad1989806f0407210bc81edc04e2762a56afd529ddda2d4393")!
        )
        let result = try client.process(
            salt: Data(hexString: "beb25379d1a8581eb5a727673a2441ee")!,
            serverPublicKey: Data(hexString: "")!
        )
        #expect(result.publicKey.hexString == "")
        #expect(result.sessionKey.hexString == "a0b5144ff95381744fe8c01561df3db6d4175c9e3b3f790075223cd41ab3bc95b635e096bf221b0c04d3e27dde06389a500c87acdff95de437efcbaeadd7fcf1")
        #expect(result.proof.hexString == "71eeb1460f9a3947e7a66e87a80e4d7e2ab3a2685f2a789e802475192aec98c5a0b973b71bb28a5b1d7ee710036c3dd9343968e7dca7a617cb21d02fd8523127")
        #expect(result.expectedServerProof.hexString == "291ef1c9f483c4e9a5a9afcc2dd2c013fad2bab2b21339ed4a77d90c55299b25a8b9cf83afaa3d19c27217a2cde36efdaa947c20a79c7428571fffb00435de93")
    }
}
